    [TestMethod]
    public void NthDateOfWeekInMonth_WhenFifthDoesNotExist_ShouldThrowExactly()
    {
        DateTime input = new DateTime(2023, 2, 1); // February 2023 has only 4 Wednesdays

        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
